// Minimal argparse replica for the test8 migration.
// Replicates the exact behavior of:
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--k1', type=str, required=True)
//   parser.add_argument('--v1', type=int, required=True)
//   parser.add_argument('--k2', type=str, required=True)
//   parser.add_argument('--v2', type=int, required=True)
//   parser.add_argument('--k3', type=str, required=True)
//   parser.add_argument('--v3', type=int, required=True)
// Pure ESM, no external dependencies, no JavaScript Map.

// Sentinel thrown to unwind to the top level after help/error output,
// so the entry file can simply catch it and return (process.exitCode
// is already set). Never call process.exit() after writing to
// stdout/stderr: buffered output could be lost.
export class ExitSignal extends Error {
  constructor() {
    super('exit');
    this.name = 'ExitSignal';
  }
}

// Option table in argparse insertion order (-h/--help is added first
// by ArgumentParser, then the six required options in definition
// order). Ambiguity candidates are listed in this order.
const OPTION_STRINGS = ['-h', '--help', '--k1', '--v1', '--k2', '--v2', '--k3', '--v3'];

const ACTIONS = Object.create(null);
ACTIONS['-h'] = { kind: 'help', display: '-h/--help' };
ACTIONS['--help'] = ACTIONS['-h'];
for (const dest of ['k1', 'v1', 'k2', 'v2', 'k3', 'v3']) {
  ACTIONS['--' + dest] = {
    kind: 'store',
    dest,
    type: dest[0] === 'v' ? 'int' : 'str',
    display: '--' + dest,
  };
}

const REQUIRED = ['k1', 'v1', 'k2', 'v2', 'k3', 'v3'];

// argparse._negative_number_matcher
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function usageLine(prog) {
  return `usage: ${prog} [-h] --k1 K1 --v1 V1 --k2 K2 --v2 V2 --k3 K3 --v3 V3`;
}

function helpText(prog) {
  return (
    usageLine(prog) +
    '\n' +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --k1 K1\n' +
    '  --v1 V1\n' +
    '  --k2 K2\n' +
    '  --v2 V2\n' +
    '  --k3 K3\n' +
    '  --v3 V3\n'
  );
}

function printHelpAndExit(prog) {
  process.stdout.write(helpText(prog));
  process.exitCode = 0;
  throw new ExitSignal();
}

function errorAndExit(prog, message) {
  process.stderr.write(usageLine(prog) + '\n' + prog + ': error: ' + message + '\n');
  process.exitCode = 2;
  throw new ExitSignal();
}

// Python repr() of a str: single quotes by default, double quotes when
// the string contains a single quote but no double quote; backslash,
// quote and control characters escaped.
function reprStr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || code === 0x7f) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else out += ch;
  }
  return out + quote;
}

// Python int(str) semantics for base 10: surrounding whitespace
// stripped, optional +/- sign, single underscores allowed between
// digits. Returns a BigInt, or null when invalid.
function parsePythonInt(s) {
  const t = s.replace(/^\s+|\s+$/g, '');
  if (!/^[+-]?\d(?:_?\d)*$/.test(t)) return null;
  return BigInt(t.replace(/_/g, ''));
}

// A token can be consumed as an option's value unless it "looks like
// an option string" (argparse: pattern 'O'). Negative-number-like
// tokens and tokens containing a space count as values, as does a
// lone '-'. '--' is never consumed as a value.
function looksLikeOption(tok) {
  if (tok.length === 0 || tok[0] !== '-') return false;
  if (tok === '-') return false;
  if (NEGATIVE_NUMBER.test(tok)) return false;
  if (tok.includes(' ')) return false;
  return true;
}

// Resolve a long option prefix (argparse._get_option_tuples, long
// branch): every known long option string starting with the prefix is
// a candidate, in definition order.
function matchLongPrefix(prefix) {
  const matches = [];
  for (const optString of OPTION_STRINGS) {
    if (optString.startsWith('--') && optString.startsWith(prefix)) {
      matches.push(optString);
    }
  }
  return matches;
}

export function parseArgs(argv, prog) {
  const values = Object.create(null);
  const seen = Object.create(null);
  const extras = [];
  let afterDoubleDash = false;

  let i = 0;
  while (i < argv.length) {
    const tok = argv[i];

    if (afterDoubleDash) {
      extras.push(tok);
      i += 1;
      continue;
    }

    // '--' stops option processing; this argparse version keeps the
    // '--' token itself in the unrecognized arguments.
    if (tok === '--') {
      afterDoubleDash = true;
      extras.push(tok);
      i += 1;
      continue;
    }

    // Not option-like: a positional; this parser defines none.
    if (!looksLikeOption(tok)) {
      extras.push(tok);
      i += 1;
      continue;
    }

    // Split an explicit "=value" suffix.
    let base = tok;
    let explicit = null;
    const eq = tok.indexOf('=');
    if (tok.startsWith('--') && eq !== -1) {
      base = tok.slice(0, eq);
      explicit = tok.slice(eq + 1);
    }

    let action = null;
    let explicitArg = explicit;

    if (Object.prototype.hasOwnProperty.call(ACTIONS, base)) {
      action = ACTIONS[base];
    } else if (tok.startsWith('--')) {
      const matches = matchLongPrefix(base);
      if (matches.length > 1) {
        errorAndExit(
          prog,
          `ambiguous option: ${tok} could match ${matches.join(', ')}`
        );
      } else if (matches.length === 1) {
        action = ACTIONS[matches[0]];
      }
      // no match: unknown optional -> extra
    } else if (eq !== -1 && Object.prototype.hasOwnProperty.call(ACTIONS, tok.slice(0, eq))) {
      // single-dash form with '=', e.g. -h=x
      action = ACTIONS[tok.slice(0, eq)];
      explicitArg = tok.slice(eq + 1);
    } else if (tok.slice(0, 2) === '-h') {
      // concatenated short option, e.g. -hx: -h takes no argument, so
      // the rest would be re-parsed as more short options (landing in
      // extras), but the help action fires first.
      action = ACTIONS['-h'];
      explicitArg = tok.slice(2);
      if (explicitArg !== '' && explicitArg[0] !== '-' && eq === -1) {
        printHelpAndExit(prog);
      }
      if (explicitArg === '') explicitArg = null;
    }

    if (action === null) {
      extras.push(tok);
      i += 1;
      continue;
    }

    if (action.kind === 'help') {
      if (explicitArg !== null) {
        errorAndExit(
          prog,
          `argument -h/--help: ignored explicit argument ${reprStr(explicitArg)}`
        );
      }
      printHelpAndExit(prog);
    }

    // store action: needs exactly one value
    let raw;
    if (explicitArg !== null) {
      raw = explicitArg;
      i += 1;
    } else if (i + 1 < argv.length && !looksLikeOption(argv[i + 1]) && argv[i + 1] !== '--') {
      raw = argv[i + 1];
      i += 2;
    } else {
      errorAndExit(prog, `argument ${action.display}: expected one argument`);
    }

    if (action.type === 'int') {
      const parsed = parsePythonInt(raw);
      if (parsed === null) {
        errorAndExit(
          prog,
          `argument ${action.display}: invalid int value: ${reprStr(raw)}`
        );
      }
      values[action.dest] = parsed;
    } else {
      values[action.dest] = raw;
    }
    seen[action.dest] = true;
  }

  // argparse checks required arguments before reporting extras.
  const missing = [];
  for (const dest of REQUIRED) {
    if (!seen[dest]) missing.push('--' + dest);
  }
  if (missing.length > 0) {
    errorAndExit(
      prog,
      `the following arguments are required: ${missing.join(', ')}`
    );
  }

  if (extras.length > 0) {
    errorAndExit(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return {
    k1: values.k1,
    v1: values.v1,
    k2: values.k2,
    v2: values.v2,
    k3: values.k3,
    v3: values.v3,
  };
}

// Differential harness: compares /output/lib/argparse.mjs against the
// reference executable for a battery of argv cases.
import { execFileSync } from 'node:child_process';
import { parseArgs, ExitSignal } from '/output/lib/argparse.mjs';

const EXE = '/workspace/dataset/test8_executable';
const PROG = 'test8_executable';

const cases = [
  ['--k1', 'i', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['-h'],
  ['--help'],
  ['--he'],
  ['--h'],
  ['--k1', 'i'],
  ['--k1', 'i', '--v1', 'abc', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1'],
  ['--v1'],
  ['--k'],
  ['--v'],
  ['--k=x'],
  ['--k1', 'i', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92', 'extra'],
  ['--k1', 'i', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92', '--bogus'],
  ['--k1', 'i', 'extra'],
  ['--k1', 'i', '--v1', '-5', '--k2', 'c', '--v2', '+7', '--k3', 't', '--v3', ' 1_0 '],
  ['--k1', 'i', '--v1', '1__0', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1', 'i', '--v1', '_10', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1', 'i', '--v1', '55', '--k1', 'x', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1=', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--v1=-5', '--k1', 'i', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1', '-h'],
  ['--v1', '-h'],
  ['--k1', 'i', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92', '-5'],
  ['--k1', 'i', '--v1', "a'b", '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1', '-5', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1', 'i', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92', '--', 'extra'],
  ['--k1', 'i', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92', '--'],
  ['--k1', 'i', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92', '--', '--', 'extra'],
  ['-h', '--k1'],
  ['--k1', '-5x', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1', ' -5', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1', '-', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--he=x'],
  ['-hx'],
  ['-h=x'],
  ['--k1', 'i', '--k1', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1x', 'i', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1', 'i', '--v1', '0b1', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1', 'i', '--v1', '\t1_2\n', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--bogus', '-h'],
  ['--k1', '--', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--', '--k1', 'i', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1=i', '--v1=55', '--k2=c', '--v2=95', '--k3=t', '--v3=92'],
  ['--K1', 'i'],
  ['--k1', 'i', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92', '--bogus1', '--bogus2'],
  ['--k1', 'i', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92', '-x'],
  ['--k1', 'i', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92', '-'],
  ['--k1', 'i', '--v1', '55', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92', ''],
  ['--k1', 'i', '--v1', '5.5', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1', 'i', '--v1', '-5.5', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  ['--k1', 'i', '--v1', '100000000000000000000', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92'],
  [],
];

function runMine(argv) {
  let out = '';
  let err = '';
  const oldOut = process.stdout.write.bind(process.stdout);
  const oldErr = process.stderr.write.bind(process.stderr);
  process.stdout.write = (s) => { out += s; return true; };
  process.stderr.write = (s) => { err += s; return true; };
  const oldCode = process.exitCode;
  process.exitCode = undefined;
  let result = null;
  let threwExit = false;
  try {
    result = parseArgs(argv, PROG);
  } catch (e) {
    if (e instanceof ExitSignal) threwExit = true;
    else throw e;
  } finally {
    process.stdout.write = oldOut;
    process.stderr.write = oldErr;
  }
  const code = threwExit ? (process.exitCode ?? 0) : 0;
  process.exitCode = oldCode;
  return { out, err, code, result };
}

function runRef(argv) {
  try {
    const out = execFileSync(EXE, argv, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    return { out, err: '', code: 0 };
  } catch (e) {
    return { out: e.stdout ?? '', err: e.stderr ?? '', code: e.status };
  }
}

let fails = 0;
for (const argv of cases) {
  const mine = runMine(argv);
  const ref = runRef(argv);
  // For successful runs the reference prints bidict output we do not
  // produce; compare only our own output expectations there.
  const okCode = mine.code === ref.code;
  const okErr = mine.err === ref.err;
  // our stdout is non-empty only for help; reference help prints the same
  const okOut = ref.code === 0 && ref.out.startsWith('usage') ? mine.out === ref.out : true;
  if (okCode && okErr && okOut) {
    // sanity on success values
  } else {
    fails += 1;
    console.log('FAIL argv=' + JSON.stringify(argv));
    console.log('  mine: code=' + mine.code + ' out=' + JSON.stringify(mine.out) + ' err=' + JSON.stringify(mine.err));
    console.log('  ref : code=' + ref.code + ' out=' + JSON.stringify(ref.out) + ' err=' + JSON.stringify(ref.err));
  }
}

// value-level checks
const v = runMine(['--k1', 'i', '--v1', '100000000000000000000', '--k2', 'c', '--v2', '+7', '--k3', 't', '--v3', ' 1_0 ']);
const r = v.result;
if (r.k1 !== 'i' || r.v1 !== 100000000000000000000n || r.v2 !== 7n || r.v3 !== 10n) {
  fails += 1;
  console.log('FAIL value check: ' + JSON.stringify(r, (k, x) => (typeof x === 'bigint' ? x.toString() + 'n' : x)));
}
// last-wins check
const v2 = runMine(['--k1', 'a', '--k1', 'b', '--v1', '1', '--v1', '2', '--k2', 'c', '--v2', '95', '--k3', 't', '--v3', '92']);
if (v2.result.k1 !== 'b' || v2.result.v1 !== 2n) {
  fails += 1;
  console.log('FAIL last-wins check');
}

console.log(fails === 0 ? 'ALL ' + cases.length + ' CASES MATCH' : fails + ' FAILURES');
